341	        // fp16 和 bf16 均为 2 字节，搬运类算子可直接用 half 路径
342	        <OpName>Kernel<half> op;
343	        op.Init(input, index, output, inputRows, srcDimSize, indexSize, totalRows, rowOffset);
344	        op.Process();
