// ============================================================
// Scatter kernel — Index per-element pattern (Mode B: one row per core)
// Applies: x.scatter_(dim, index, src, reduce=...)
// Strategy: each core loads one self row into UB, then scatter src
//           tile-by-tile along K dimension, write self row back.
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t UB_CAPACITY = 192 * 1024;

template<typename T>
class ScatterKernel {
public:
    __aicore__ inline ScatterKernel() {}

    __aicore__ inline void Init(GM_ADDR self, GM_ADDR index, GM_ADDR src,
                                int64_t batchRows, int64_t innerSize, int64_t K,
                                int64_t tileK, int64_t rowOffset, int64_t reduceMode);
    __aicore__ inline void Process();

private:
    __aicore__ inline void ProcessRow(int64_t outerIdx);

    TPipe pipe;

    // UB buffers
    TBuf<TPosition::VECIN> selfBuf;       // self row (innerSize elements)
    TBuf<TPosition::VECIN> srcBuf;        // src tile (tileK elements)
    TBuf<TPosition::VECIN> indexBuf;      // index tile (tileK int32 elements)
    TBuf<TPosition::VECCALC> srcFp32Buf;  // src fp32 tile (fp16/bf16 path only)

    GlobalTensor<T> selfGm;
    GlobalTensor<int32_t> indexGm;
    GlobalTensor<T> srcGm;

    int64_t batchRows_ = 0;
    int64_t innerSize_ = 0;
    int64_t K_ = 0;
    int64_t tileK_ = 0;
    int64_t rowOffset_ = 0;
    int64_t reduceMode_ = 0;        // 0=replace, 1=add, 2=multiply
    int64_t innerRowBytes_ = 0;     // aligned self row size in bytes
    int64_t innerRowElems_ = 0;     // aligned self row element count
};

// =========================== Init ============================

template<typename T>
__aicore__ inline void ScatterKernel<T>::Init(
    GM_ADDR self, GM_ADDR index, GM_ADDR src,
    int64_t batchRows, int64_t innerSize, int64_t K,
    int64_t tileK, int64_t rowOffset, int64_t reduceMode)
{
    batchRows_ = batchRows;
    innerSize_ = innerSize;
    K_ = K;
    tileK_ = tileK;
    rowOffset_ = rowOffset;
    reduceMode_ = reduceMode;

    selfGm.SetGlobalBuffer((__gm__ T*)self);
    indexGm.SetGlobalBuffer((__gm__ int32_t*)index);
    srcGm.SetGlobalBuffer((__gm__ T*)src);

    // 32-byte aligned row size
    innerRowBytes_ = ((innerSize * sizeof(T) + 31) / 32) * 32;
    innerRowElems_ = innerRowBytes_ / sizeof(T);

    // Allocate UB buffers
    pipe.InitBuffer(selfBuf, innerRowBytes_);
    pipe.InitBuffer(indexBuf, static_cast<uint32_t>(tileK * sizeof(int32_t)));
    pipe.InitBuffer(srcBuf, static_cast<uint32_t>(tileK * sizeof(T)));

    if constexpr (sizeof(T) == sizeof(float)) {
        // fp32: no extra cast buffer needed
    } else {
        // fp16/bf16: need fp32 buffer for src cast
        pipe.InitBuffer(srcFp32Buf, static_cast<uint32_t>(tileK * sizeof(float)));
    }
}

// =========================== Process ============================

template<typename T>
__aicore__ inline void ScatterKernel<T>::Process()
{
    int64_t blockIdx = GetBlockIdx();
    if (blockIdx >= batchRows_) return;

    int64_t outerIdx = rowOffset_ + blockIdx;
    ProcessRow(outerIdx);
}

// =========================== ProcessRow ============================

template<typename T>
__aicore__ inline void ScatterKernel<T>::ProcessRow(int64_t outerIdx)
{
    // 1. Load self row from GM into UB
    LocalTensor<T> selfLocal = selfBuf.Get<T>();
    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        DataCopyPad(selfLocal, selfGm[outerIdx * innerSize_], copyParams, padParams);
    }
    PipeBarrier<PIPE_ALL>();

    // 2. Scatter along K dimension tile by tile
    int64_t tileNum = (K_ + tileK_ - 1) / tileK_;

    for (int64_t t = 0; t < tileNum; t++) {
        int64_t tileStart = t * tileK_;
        int64_t curTileK = (t == tileNum - 1) ? (K_ - tileStart) : tileK_;

        // Load index tile
        LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
        {
            DataCopyExtParams copyParams;
            copyParams.blockCount = 1;
            copyParams.blockLen = static_cast<uint32_t>(curTileK * sizeof(int32_t));
            copyParams.srcStride = 0;
            copyParams.dstStride = 0;
            DataCopyPadExtParams<int32_t> padParams;
            padParams.isPad = false;
            DataCopyPad(indexLocal, indexGm[outerIdx * K_ + tileStart],
                        copyParams, padParams);
        }
        PipeBarrier<PIPE_ALL>();

        // Load src tile
        LocalTensor<T> srcLocal = srcBuf.Get<T>();
        {
            DataCopyExtParams copyParams;
            copyParams.blockCount = 1;
            copyParams.blockLen = static_cast<uint32_t>(curTileK * sizeof(T));
            copyParams.srcStride = 0;
            copyParams.dstStride = 0;
            DataCopyPadExtParams<T> padParams;
            padParams.isPad = false;
            DataCopyPad(srcLocal, srcGm[outerIdx * K_ + tileStart],
                        copyParams, padParams);
        }
        PipeBarrier<PIPE_ALL>();

        // Scatter: per-element update
        if constexpr (sizeof(T) == sizeof(float)) {
            // === FP32 path: direct computation ===
            for (int64_t i = 0; i < curTileK; i++) {
                int32_t idx = indexLocal.GetValue(i);
                float srcVal = srcLocal.GetValue(i);
                if (reduceMode_ == 0) {
                    // replace
                    selfLocal.SetValue(idx, srcVal);
                } else if (reduceMode_ == 1) {
                    // add
                    float curVal = selfLocal.GetValue(idx);
                    selfLocal.SetValue(idx, curVal + srcVal);
                } else {
                    // multiply
                    float curVal = selfLocal.GetValue(idx);
                    selfLocal.SetValue(idx, curVal * srcVal);
                }
            }
        } else {
            // === FP16/BF16 path: cast to fp32, compute, cast back ===
            LocalTensor<float> srcFp32Local = srcFp32Buf.Get<float>();
            Cast(srcFp32Local, srcLocal, RoundMode::CAST_NONE,
                 static_cast<uint32_t>(curTileK));
            PipeBarrier<PIPE_ALL>();

            for (int64_t i = 0; i < curTileK; i++) {
                int32_t idx = indexLocal.GetValue(i);
                float srcVal = srcFp32Local.GetValue(i);
                float curVal = (float)selfLocal.GetValue(idx);
                float result;
                if (reduceMode_ == 0) {
                    result = srcVal;
                } else if (reduceMode_ == 1) {
                    result = curVal + srcVal;
                } else {
                    result = curVal * srcVal;
                }
                selfLocal.SetValue(idx, (T)result);
            }
        }
        PipeBarrier<PIPE_ALL>();
    }

    // 3. Write self row back to GM
    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPad(selfGm[outerIdx * innerSize_], selfLocal, copyParams);
    }
    PipeBarrier<PIPE_ALL>();
}

// =========================== Kernel Entry ============================

extern "C" __global__ __aicore__ void scatter(
    GM_ADDR self, GM_ADDR index, GM_ADDR src,
    int64_t batchRows, int64_t innerSize, int64_t K,
    int64_t tileK, int64_t rowOffset, int64_t reduceMode,
    int64_t dtypeSize)
{
    if (dtypeSize == 4) {
        ScatterKernel<float> op;
        op.Init(self, index, src, batchRows, innerSize, K, tileK, rowOffset, reduceMode);
        op.Process();
    } else if (dtypeSize == 2) {
        // fp16 and bf16 both 2 bytes, use half path
        ScatterKernel<half> op;
        op.Init(self, index, src, batchRows, innerSize, K, tileK, rowOffset, reduceMode);
        op.Process();
    }
}
