// ============================================================
// Scatter op_host — per-element index pattern, mode B (one row per core)
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_scatter.h"

namespace ascend_kernel {

at::Tensor scatter(
    const at::Tensor& x,
    int64_t dim,
    const at::Tensor& index,
    const at::Tensor& src,
    const std::string& reduce)
{
    // ---- Input validation ----
    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1,
                "scatter: x must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "scatter: index must be on NPU device");
    TORCH_CHECK(src.device().type() == at::DeviceType::PrivateUse1,
                "scatter: src must be on NPU device");

    int64_t ndim = x.dim();
    if (dim < 0) dim += ndim;

    TORCH_CHECK(dim >= 0 && dim < ndim,
                "scatter: dim out of range, got dim=", dim);
    TORCH_CHECK(index.dim() == ndim,
                "scatter: index must have same ndim as x");
    TORCH_CHECK(src.sizes() == index.sizes(),
                "scatter: src must have same shape as index");

    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "scatter: only float32, float16 and bfloat16 are supported");

    // ---- Contiguous conversion ----
    at::Tensor xContiguous = x.contiguous();
    at::Tensor indexContiguous = index.contiguous();
    at::Tensor srcContiguous = src.contiguous();

    int64_t dtypeSize = xContiguous.element_size();

    // ---- Reduce mode ----
    int64_t reduceMode = 0;  // 0=replace
    if (reduce == "add") {
        reduceMode = 1;
    } else if (reduce == "multiply") {
        reduceMode = 2;
    }

    // ---- Dimension unification ----
    // Transpose dim to last, reshape to 2D: [outerSize, innerSize/K]
    //   outerSize = product of all dims except dim
    //   innerSize = x.size(dim)
    //   K = index.size(dim)
    int64_t outerSize = 1;
    for (int64_t i = 0; i < ndim; i++) {
        if (i != dim) outerSize *= xContiguous.size(i);
    }
    int64_t innerSize = xContiguous.size(dim);
    int64_t K = indexContiguous.size(dim);

    // Transpose dim to last, then reshape
    auto xTransposed = xContiguous.transpose(dim, -1).contiguous();
    auto selfFlat = xTransposed.reshape({outerSize, innerSize});

    auto indexTransposed = indexContiguous.transpose(dim, -1).contiguous();
    auto indexInt32 = indexTransposed.to(at::kInt);
    auto indexFlat = indexInt32.reshape({outerSize, K});

    auto srcTransposed = srcContiguous.transpose(dim, -1).contiguous();
    auto srcFlat = srcTransposed.reshape({outerSize, K});

    // Output: clone x
    auto outputFlat = selfFlat.clone();

    // ---- Platform info ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- Compute tileK ----
    // UB allocation: selfBuf = innerSize * dtypeSize (aligned 32B)
    //                indexBuf = tileK * 4
    //                srcBuf = tileK * dtypeSize
    //                srcFp32Buf (fp16/bf16): tileK * 4
    // For fp32: tileK * 8 + alignedSelf
    // For fp16/bf16: tileK * 10 + alignedSelf
    int64_t alignedSelfBytes = ((innerSize * dtypeSize + 31) / 32) * 32;
    int64_t perKOverhead;
    if (dtypeSize == 4) {
        perKOverhead = 8;  // index(int32=4) + src(fp32=4)
    } else {
        perKOverhead = 10; // index(int32=4) + src(fp16=2) + srcFp32(4)
    }

    int64_t ubAvail = static_cast<int64_t>(ubSize) - alignedSelfBytes;
    int64_t tileK = ubAvail / perKOverhead;
    if (tileK < 1) tileK = 1;
    if (tileK > K) tileK = K;

    // 32-byte alignment for tileK elements of int32
    int64_t alignElems = 32 / static_cast<int64_t>(sizeof(int32_t));  // = 8
    tileK = (tileK / alignElems) * alignElems;
    if (tileK < 1) tileK = 1;

    // ---- Batch launch: one row per core ----
    int64_t processed = 0;
    while (processed < outerSize) {
        int64_t batchRows = outerSize - processed;
        if (batchRows > coreNum) batchRows = coreNum;
        uint32_t blockDim = static_cast<uint32_t>(batchRows);
        if (blockDim < 1) blockDim = 1;

        // EXEC_KERNEL_CMD parameters must all be lvalues
        auto outputBatch = outputFlat.narrow(0, processed, batchRows);
        auto indexBatch = indexFlat.narrow(0, processed, batchRows);
        auto srcBatch = srcFlat.narrow(0, processed, batchRows);
        int64_t rowOffset = processed;

        EXEC_KERNEL_CMD(scatter, blockDim, outputBatch, indexBatch, srcBatch,
                        batchRows, innerSize, K, tileK, rowOffset, reduceMode,
                        dtypeSize);

        processed += batchRows;
    }

    // ---- Reshape output back to original shape ----
    outputFlat = outputFlat.reshape(xTransposed.sizes());
    auto result = outputFlat.transpose(ndim - 1, dim).contiguous();
    return result;
}

}  // namespace ascend_kernel
