11	// ============================================================
12	// Scatter op_host — per-element index pattern, mode B (one row per core)
13	// ============================================================
14	
15	#include "torch_kernel_helper.h"
16	#include "tiling/platform/platform_ascendc.h"
17	#include "aclrtlaunch_scatter.h"
18	
19	namespace ascend_kernel {
20	
21	at::Tensor scatter(
22	    const at::Tensor& x,
23	    int64_t dim,
24	    const at::Tensor& index,
25	    const at::Tensor& src,
26	    const std::string& reduce)
27	{
28	    // ---- Input validation ----
29	    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1,
30	                "scatter: x must be on NPU device");
31	    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
32	                "scatter: index must be on NPU device");
33	    TORCH_CHECK(src.device().type() == at::DeviceType::PrivateUse1,
34	                "scatter: src must be on NPU device");
35	
36	    int64_t ndim = x.dim();
37	    if (dim < 0) dim += ndim;
38	
39	    TORCH_CHECK(dim >= 0 && dim < ndim,
40	                "scatter: dim out of range, got dim=", dim);
41	    TORCH_CHECK(index.dim() == ndim,
42	                "scatter: index must have same ndim as x");
43	    TORCH_CHECK(src.sizes() == index.sizes(),
44	                "scatter: src must have same shape as index");
45	
46	    TORCH_CHECK(x.scalar_type() == at::kFloat ||
47	                x.scalar_type() == at::kHalf ||
48	                x.scalar_type() == at::kBFloat16,
49	                "scatter: only float32, float16 and bfloat16 are supported");
50	
51	    // ---- Contiguous conversion ----
52	    at::Tensor xContiguous = x.contiguous();
53	    at::Tensor indexContiguous = index.contiguous();
54	    at::Tensor srcContiguous = src.contiguous();
55	
56	    int64_t dtypeSize = xContiguous.element_size();
57	
58	    // ---- Reduce mode ----
59	    int64_t reduceMode = 0;  // 0=replace
60	    if (reduce == "add") {
61	        reduceMode = 1;
62	    } else if (reduce == "multiply") {
63	        reduceMode = 2;
64	    }
65	
66	    // ---- Dimension unification ----
67	    // Transpose dim to last, reshape to 2D: [outerSize, innerSize/K]
68	    int64_t innerSize = xContiguous.size(dim);
69	    int64_t K = indexContiguous.size(dim);
70	
71	    auto xTransposed = xContiguous.transpose(dim, -1).contiguous();
72	    auto selfFlat = xTransposed.reshape({-1, innerSize});
73	    int64_t outerSize = selfFlat.size(0);
74	
75	    auto indexTransposed = indexContiguous.transpose(dim, -1).contiguous();
76	    auto indexInt32 = indexTransposed.to(at::kInt);
77	    auto indexFlat = indexInt32.reshape({outerSize, K});
78	
79	    auto srcTransposed = srcContiguous.transpose(dim, -1).contiguous();
80	    auto srcFlat = srcTransposed.reshape({outerSize, K});
81	
82	    // ---- Cast bfloat16 to float32 for kernel (AscendC half != bfloat16) ----
83	    at::Tensor selfFlatKernel = selfFlat;
84	    at::Tensor srcFlatKernel = srcFlat;
85	    at::Tensor outputFlatKernel;
86	    int64_t dtypeSizeKernel = dtypeSize;
87	    bool isBf16 = (xContiguous.scalar_type() == at::kBFloat16);
88	    if (isBf16) {
89	        selfFlatKernel = selfFlat.to(at::kFloat);
90	        srcFlatKernel = srcFlat.to(at::kFloat);
91	        dtypeSizeKernel = 4;  // use fp32 kernel
92	    }
93	    outputFlatKernel = selfFlatKernel.clone();
94	
95	    // ---- Platform info ----
96	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
97	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
98	    uint64_t ubSize;
99	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
100	
101	    // ---- Compute tileK ----
102	    // UB allocation: selfBuf = innerSize * dtypeSize (aligned 32B)
103	    //                indexBuf = tileK * 4
104	    //                srcBuf = tileK * dtypeSize
105	    //                srcFp32Buf (fp16/bf16): tileK * 4
106	    // For fp32: tileK * 8 + alignedSelf
107	    // For fp16/bf16: tileK * 10 + alignedSelf
108	    int64_t alignedSelfBytes = ((innerSize * dtypeSize + 31) / 32) * 32;
109	    int64_t perKOverhead;
110	    if (dtypeSize == 4) {
111	        perKOverhead = 8;  // index(int32=4) + src(fp32=4)
112	    } else {
113	        perKOverhead = 10; // index(int32=4) + src(fp16=2) + srcFp32(4)
114	    }
115	
116	    int64_t ubAvail = static_cast<int64_t>(ubSize) - alignedSelfBytes;
117	    int64_t tileK = ubAvail / perKOverhead;
118	    if (tileK < 1) tileK = 1;
119	    if (tileK > K) tileK = K;
120	
121	    // 32-byte alignment for tileK elements of int32
122	    int64_t alignElems = 32 / static_cast<int64_t>(sizeof(int32_t));  // = 8
123	    tileK = (tileK / alignElems) * alignElems;
124	    if (tileK < 1) tileK = 1;
125	
126	    // ---- Batch launch: one row per core ----
127	    int64_t processed = 0;
128	    while (processed < outerSize) {
129	        int64_t batchRows = outerSize - processed;
130	        if (batchRows > coreNum) batchRows = coreNum;
131	        uint32_t blockDim = static_cast<uint32_t>(batchRows);
132	        if (blockDim < 1) blockDim = 1;
133	
134	        // EXEC_KERNEL_CMD parameters must all be lvalues
135	        auto outputBatch = outputFlatKernel.narrow(0, processed, batchRows);
136	        auto indexBatch = indexFlat.narrow(0, processed, batchRows);
137	        auto srcBatch = srcFlatKernel.narrow(0, processed, batchRows);
138	        int64_t rowOffset = processed;
139	
140	        EXEC_KERNEL_CMD(scatter, blockDim, outputBatch, indexBatch, srcBatch,
141	                        batchRows, innerSize, K, tileK, rowOffset, reduceMode,
142	                        dtypeSizeKernel);
143	
144	        processed += batchRows;
145	    }
146	
147	    // ---- Reshape output back to original shape ----
148	    // If bfloat16 was cast to float32, cast back
149	    if (isBf16) {
150	        outputFlatKernel = outputFlatKernel.to(at::kBFloat16);
151	    }
152	    outputFlatKernel = outputFlatKernel.reshape(xTransposed.sizes());
153	    auto result = outputFlatKernel.transpose(ndim - 1, dim).contiguous();
154	    return result;
155	}
156	
157	}  // namespace ascend_kernel
